def check_circulant(N, gens):
    # gens is a list of generators
    # BFS to find shortest cycle
    from collections import deque

    # We can just check if there's any non-trivial sum of length <= 6 that equals 0 mod N
    # A sum is valid if it doesn't contain a step and its immediate reverse.
    # Actually, just BFS from 0.

    q = deque([(0, -1, 0)]) # (current_node, parent_node, depth)
    visited = {0: 0}

    while q:
        u, p, d = q.popleft()
        if d == 3: # We only need to check up to depth 3 to find cycles up to length 6
            continue

        for g in gens:
            for step in (g, -g):
                v = (u + step) % N
                if v == p:
                    continue
                if v in visited:
                    cycle_len = d + 1 + visited[v]
                    if cycle_len <= 6:
                        return False
                else:
                    visited[v] = d + 1
                    q.append((v, u, d + 1))
    return True

