from pysat.solvers import Glucose3
import itertools
import networkx as nx

def solve():
    N = 25

    def edge_var(i, j):
        if i > j:
            i, j = j, i
        return i * N + j + 1 # 1-indexed

    solver = Glucose3()

    # Degree constraints
    for i in range(N):
        edges = [edge_var(i, j) for j in range(N) if i != j]
        # At least 3
        # We can use combinations
        # Actually, PySAT has CardEnc
        from pysat.card import CardEnc
        cnf1 = CardEnc.atleast(lits=edges, bound=3, vpool=None)
        for clause in cnf1.clauses:
            solver.add_clause(clause)
        cnf2 = CardEnc.atmost(lits=edges, bound=7, vpool=None)
        for clause in cnf2.clauses:
            solver.add_clause(clause)

    # CEGAR loop
    import collections

    def find_short_cycle(edges_list):
        adj = collections.defaultdict(list)
        for u, v in edges_list:
            adj[u].append(v)
            adj[v].append(u)

        # BFS to find shortest cycle
        for start in range(N):
            q = collections.deque([(start, -1, 0)])
            visited = {start: 0}
            parent = {start: -1}

            while q:
                u, p, d = q.popleft()
                if d == 3:
                    continue
                for v in adj[u]:
                    if v == p:
                        continue
                    if v in visited:
                        cycle_len = d + 1 + visited[v]
                        if cycle_len <= 6:
                            # Reconstruct cycle
                            cycle_edges = []
                            curr = u
                            while curr != start:
                                cycle_edges.append((curr, parent[curr]))
                                curr = parent[curr]
                            curr = v
                            while curr != start:
                                cycle_edges.append((curr, parent[curr]))
                                curr = parent[curr]
                            cycle_edges.append((u, v))
                            return cycle_edges
                    else:
                        visited[v] = d + 1
                        parent[v] = u
                        q.append((v, u, d + 1))
        return None

    iters = 0
    while solver.solve():
        iters += 1
        model = solver.get_model()
        edges_list = []
        for i in range(N):
            for j in range(i+1, N):
                if model[edge_var(i, j) - 1] > 0:
                    edges_list.append((i, j))

        cycle = find_short_cycle(edges_list)
        if cycle is None:
            print(f"Found solution after {iters} iterations!")
            print(edges_list)
            return edges_list

        # Add clause to forbid this cycle
        clause = []
        for u, v in cycle:
            clause.append(-edge_var(u, v))
        solver.add_clause(clause)

        if iters % 100 == 0:
            print(f"Iteration {iters}, added clause of length {len(clause)}")

    print("UNSAT")
    return None

